export const OPENING_SCENES = Object.freeze([
 {image:'01-outbreak.png',chapter:'The outbreak',title:'The world stopped. The dead didn’t.',alt:'Four survivors watch their rural town fall as smoke rises at sunset.',story:'The radios went quiet first. Then the roads filled with people running from neighbors they no longer recognized. Hank left town with Mara, Teo, June—and the seeds of another harvest.',lesson:'You guide all four survivors. Keep your people alive and protect the farmhouse.'},
 {image:'02-arrival.png',chapter:'The road home',title:'One road. Four survivors. A chance.',alt:'Hank, Mara, Teo and June reach a fenced farmhouse beyond the forest.',story:'Beyond the woods, an old farm still stood. There was a house, a barn, a few supplies, and a fence between them and the world. It would have to be enough.',lesson:'Open Operations (O) to assign jobs. Farmers tend crops, builders finish projects, defenders collect shotguns, and scouts bring supplies through the south gate.'},
 {image:'03-homestead.png',chapter:'Make it home',title:'Tomorrow starts with what you grow today.',alt:'The four survivors plant crops, mend fences, organize supplies and prepare food.',story:'They cleared the beds, counted the cans, and divided the work. Every seed was a promise. Every meal around the same table made them a little less alone.',lesson:'Keep food and drinking water for each survivor at breakfast; Teo eats an extra helping. Crops follow your upgrade level automatically. At breakfast, Farm life opens the kitchen, preserved pantry, cattle breeding and survivor bonds.'},
 {image:'04-nightfall.png',chapter:'The first night',title:'Keep the lights burning.',alt:'Survivors guard the closed farm gate while zombies emerge beyond the trees.',story:'At dusk, shapes began to move between the trees. The generator coughed to life. For tonight, the little pools of light—and the people standing beside them—were all they had.',lesson:'Save gasoline, shells and repair scrap. Nights 1 and 2 bring stragglers; night 3 brings a horde of 30. Finish the zombies before greeting dawn. Press N when ready for the next phase. Scouting teams use the south gate.'},
]);

export function installOpening({game,sync,focusGame}) {
 const dialog=document.createElement('dialog');dialog.id='opening-dialog';dialog.className='opening-dialog';dialog.setAttribute('aria-labelledby','opening-title');dialog.setAttribute('aria-describedby','opening-story');
 dialog.innerHTML='<div class="opening-book"><header class="opening-header"><span class="opening-brand">LAST HARVEST <small>Before the first morning</small></span><button type="button" id="opening-skip" class="text-button">Skip opening →</button></header><figure class="opening-art"><img id="opening-image" alt="" decoding="async"><span id="opening-image-fallback" hidden>The road to Last Harvest</span><figcaption id="opening-chapter"></figcaption></figure><section class="opening-copy" aria-live="polite" aria-atomic="true"><p id="opening-count" class="eyebrow"></p><h2 id="opening-title"></h2><p id="opening-story"></p><div class="opening-lesson"><span>TO SURVIVE</span><p id="opening-lesson"></p></div></section><footer class="opening-footer"><button type="button" id="opening-back" class="secondary-button">← Back</button><nav id="opening-pages" aria-label="Opening scenes"></nav><button type="button" id="opening-next" class="primary-button">Next →</button></footer></div>';
 document.body.append(dialog);
 const $=id=>dialog.querySelector('#'+id),image=$('opening-image');let index=0,complete=null,resumeAfter=false,ending=false;
 function render(){const scene=OPENING_SCENES[index];image.hidden=false;$('opening-image-fallback').hidden=true;image.src=new URL('./assets/opening/'+scene.image,import.meta.url).href;image.alt=scene.alt;$('opening-chapter').textContent=scene.chapter;$('opening-count').textContent='CHAPTER '+String(index+1).padStart(2,'0')+' / '+OPENING_SCENES.length;$('opening-title').textContent=scene.title;$('opening-story').textContent=scene.story;
  const goal=game.s.campaign?' Repair the radio, contact another settlement, and hold through night 10.':game.s.endless?' Endure as many nights as you can.':' Survive the first three nights; you can continue afterward.';
  $('opening-lesson').textContent=scene.lesson+(index===OPENING_SCENES.length-1?goal:'');$('opening-back').disabled=index===0;$('opening-next').textContent=index===OPENING_SCENES.length-1?(complete?'See the starting pack →':'Return to the farm →'):'Next →';$('opening-pages').innerHTML=OPENING_SCENES.map((s,i)=>'<button type="button" data-scene="'+i+'" aria-label="Scene '+(i+1)+': '+s.chapter+'" '+(i===index?'aria-current="step"':'')+'><span aria-hidden="true">'+(i+1)+'</span></button>').join('');dialog.querySelector('.opening-copy').scrollTop=0;
  const next=OPENING_SCENES[index+1];if(next){const preload=new Image();preload.src=new URL('./assets/opening/'+next.image,import.meta.url).href;}
 }
 image.addEventListener('error',()=>{image.hidden=true;$('opening-image-fallback').hidden=false;});
 function finish(){if(ending||!dialog.open)return;ending=true;dialog.close();}
 function next(){if(index===OPENING_SCENES.length-1)finish();else{index++;render();}}
 $('opening-next').addEventListener('click',next);$('opening-back').addEventListener('click',()=>{index=Math.max(0,index-1);render();});$('opening-skip').addEventListener('click',finish);
 $('opening-pages').addEventListener('click',e=>{const b=e.target.closest('[data-scene]');if(b){index=Number(b.dataset.scene);render();}});
 dialog.addEventListener('cancel',e=>{e.preventDefault();finish();});
 dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();next();}else if(e.key==='ArrowLeft'){e.preventDefault();index=Math.max(0,index-1);render();}});
 dialog.addEventListener('close',()=>{const done=complete;complete=null;if(done)done();else if(resumeAfter&&game.s.mode==='paused')game.resume();resumeAfter=false;sync();if(!document.querySelector('dialog[open]'))focusGame();});
 return {open(done=null,resume=game.s.mode==='playing'){if(dialog.open||document.querySelector('dialog[open]'))return false;index=0;ending=false;complete=done;resumeAfter=resume;if(game.s.mode==='playing')game.pause();sync();render();dialog.showModal();$('opening-next').focus();return true;},get active(){return dialog.open;}};
}
